function validate([root, p, q]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  // Each real node owns the next two entries as its children; extra entries do not belong to the tree.
  let slots = 1;
  for (let i = 0; i < root.length; i++) {
    if (i >= slots) return 'The tree has entries that no node can hold.';
    if (root[i] !== null) slots += 2;
  }
  const values = root.filter(v => v !== null);
  if (values.length > 10000) return 'The tree has at most 10^4 nodes.';
  const seen = new Set();
  for (const v of values) {
    if (!Number.isInteger(v) || v < 0 || v > 1e9) return 'Each node value is between 0 and 10^9.';
    if (seen.has(v)) return 'Node values must be distinct.';
    seen.add(v);
  }
  if (!seen.has(p)) return 'p must be the value of a node in the tree.';
  if (!seen.has(q)) return 'q must be the value of a node in the tree.';
  return null;
}

