function findDistance(root, p, q) {
  function lowestAncestor(node) {
    if (node === null || node.val === p || node.val === q) {
      return node;
    }
    const left = lowestAncestor(node.left);
    const right = lowestAncestor(node.right);
    if (left !== null && right !== null) {
      return node;
    }
    return left !== null ? left : right;
  }

  function depth(node, target) {
    if (node === null) {
      return -1;
    }
    if (node.val === target) {
      return 0;
    }
    const below = Math.max(depth(node.left, target), depth(node.right, target));
    return below === -1 ? -1 : below + 1;
  }

  const ancestor = lowestAncestor(root);
  return depth(ancestor, p) + depth(ancestor, q);
}

