function findDistance(root, p, q) {
  // Turn the tree into an undirected graph, then walk outwards from p one layer at a time.
  const neighbours = new Map();
  const link = (a, b) => {
    if (!neighbours.has(a)) neighbours.set(a, []);
    neighbours.get(a).push(b);
  };
  const stack = [root];
  neighbours.set(root.val, []);
  while (stack.length) {
    const node = stack.pop();
    for (const child of [node.left, node.right]) {
      if (!child) continue;
      link(node.val, child.val);
      link(child.val, node.val);
      stack.push(child);
    }
  }
  let layer = [p];
  const seen = new Set([p]);
  for (let steps = 0; layer.length; steps++) {
    if (layer.includes(q)) return steps;
    const next = [];
    for (const v of layer) for (const w of neighbours.get(v)) if (!seen.has(w)) { seen.add(w); next.push(w); }
    layer = next;
  }
  return -1;
}

