function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 900 + Math.floor(rand() * 100) : 1 + Math.floor(rand() * 10);
  // Some trees start with a long downward chain, which makes deep paths.
  const chain = rand() < 0.3 ? 1 + Math.floor(rand() * n) : 1;
  const nodes = [{ left: null, right: null }];
  for (let i = 1; i < chain; i++) {
    nodes[i - 1][rand() < 0.5 ? 'left' : 'right'] = i;
    nodes.push({ left: null, right: null });
  }
  const slots = [[chain - 1, 'left'], [chain - 1, 'right']];
  for (let i = chain; i < n; i++) {
    const k = Math.floor(rand() * slots.length);
    const [parent, side] = slots[k];
    slots[k] = slots[slots.length - 1];
    slots.pop();
    nodes[parent][side] = i;
    nodes.push({ left: null, right: null });
    slots.push([i, 'left'], [i, 'right']);
  }
  // Distinct values: small trees draw from 0..30 (sometimes with the extremes), large ones from 0..10^9.
  const used = new Set();
  const values = [];
  if (!large && rand() < 0.3) { values.push(0); used.add(0); }
  if (!large && rand() < 0.3 && values.length < n) { values.push(1e9); used.add(1e9); }
  while (values.length < n) {
    const v = large ? Math.floor(rand() * 1e9) + 1 : Math.floor(rand() * 31);
    if (!used.has(v)) { used.add(v); values.push(v); }
  }
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [values[i], values[j]] = [values[j], values[i]];
  }
  // Level-order serialisation with null for missing children, trailing nulls removed.
  const out = [];
  const queue = [0];
  for (let at = 0; at < queue.length; at++) {
    if (queue[at] === null) { out.push(null); continue; }
    out.push(values[queue[at]]);
    queue.push(nodes[queue[at]].left, nodes[queue[at]].right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  const p = values[Math.floor(rand() * n)];
  const q = rand() < 0.1 ? p : values[Math.floor(rand() * n)];
  return [out, p, q];
}
